import { memo } from 'react'
import { MarkdownEditor } from '../../editor/markdown_editor'
import { projectSessionService } from '../../../services/project/project_session_service'
import { attachFilesToNewCardMarkdown } from '../../../services/attachments/new_card_attachment_workflow'
import type { MarkdownDraft } from '../../../services/markdown/markdown_draft'

interface NewCardMarkdownEditorProps {
    draft: MarkdownDraft
}

const handleImagePaste = (file: File, insertMarkdown: (markdown: string) => void) => (
    projectSessionService.pasteNewCardImage(file, insertMarkdown)
)
const handleAttachments = (files: File[], insertMarkdown: (markdown: string) => void) => (
    attachFilesToNewCardMarkdown(files, insertMarkdown)
)

/** Lifetime-stable Markdown editor boundary for a new-card draft. */
export const NewCardMarkdownEditor = memo(function NewCardMarkdownEditor(props: NewCardMarkdownEditorProps) {
    const { draft } = props

    return (
        <MarkdownEditor
            attachmentHandler={handleAttachments}
            draft={draft}
            hideAttachmentControl
            hideToolbar
            imagePasteHandler={handleImagePaste}
        />
    )
})

import { cleanup, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import { AppThemeProvider } from '../../../theme/theme_provider'
import { NewCardMarkdownEditor } from './new_card_markdown_editor'
import { MarkdownDraft } from '../../../services/markdown/markdown_draft'

afterEach(cleanup)

describe('NewCardMarkdownEditor', () => {
    it('suppresses toolbar controls while retaining attachment drops', () => {
        const draft = new MarkdownDraft('')
        render(
            <AppThemeProvider>
                <NewCardMarkdownEditor draft={draft} />
            </AppThemeProvider>,
        )

        expect(screen.queryByRole('button', { name: 'Attach files' })).not.toBeInTheDocument()
        expect(screen.queryByRole('button', { name: 'Bold' })).not.toBeInTheDocument()
    })
})

import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { ListCardCommitDiffPanel } from '../card_view/list_card_commit_diff_panel'
import { cardMarkdownDataSource, type CardDocumentClosedDetail } from '../editor/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { MarkdownEditor } from '../editor/markdown_editor'
import { ListEditorToolbarControls } from './list_editor_toolbar_controls'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { attachFilesToCardMarkdown } from '../../services/attachments/attachment_workflow'

interface CardEditorProps {
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

/** Lifetime-stable list-card editor with private history. */
export const CardEditor = memo(function CardEditor(props: CardEditorProps) {
    const { cardTypes, statusColors } = props
    const readOnly = useProjectReadOnly()
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => cardMarkdownDataSource.pasteImage('list-card', file, insertMarkdown),
        [],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = cardMarkdownDataSource.getActiveCard('list-card')
        if (!card) throw new Error('Cannot attach files without an active list card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [])

    useEffect(() => {
        const handleCardDocumentClosed = (event: Event) => {
            const { binding, document } = (event as CustomEvent<CardDocumentClosedDetail>).detail
            if (binding !== 'list-card') return

            historyStore.discardDocument(document)
        }
        cardMarkdownDataSource.addEventListener('cardDocumentClosed', handleCardDocumentClosed)

        return () => {
            cardMarkdownDataSource.removeEventListener('cardDocumentClosed', handleCardDocumentClosed)
        }
    }, [historyStore])

    const toolbarContents = useCallback(() => (
        <ListEditorToolbarControls
            cardTypes={cardTypes}
            historyStore={historyStore}
            readOnly={readOnly}
            statusColors={statusColors}
        />
    ), [cardTypes, historyStore, readOnly, statusColors])

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}>
            <ListCardCommitDiffPanel>
                <MarkdownEditor
                    attachmentHandler={handleAttachments}
                    binding="list-card"
                    dataSource={cardMarkdownDataSource}
                    historyStore={historyStore}
                    imagePasteHandler={handleImagePaste}
                    readOnly={readOnly}
                    toolbarContents={toolbarContents}
                />
            </ListCardCommitDiffPanel>
        </Box>
    )
})

import { Box } from '@mui/material'
import { memo, useCallback } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { MarkdownEditor } from '../editor/markdown_editor'
import type { CardMarkdownDataSource } from '../editor/card_markdown_data_source'
import type { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { CardPopupToolbarControls } from './card_popup_toolbar_controls'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { attachFilesToCardMarkdown } from '../../services/attachments/attachment_workflow'

interface CardBodyEditorProps {
    cardTypes: CardTypeConfig[]
    dataSource: CardMarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    isMobile?: boolean
    isFullscreen: boolean
    onToggleFullscreen: () => void
    overlayContainer?: HTMLElement | null
    statusColors: Map<string, string>
}

/**
 * Body editing surface for a card, bound directly to the card Markdown data source.
 */
export const CardBodyEditor = memo(function CardBodyEditor(props: CardBodyEditorProps) {
    const {cardTypes, dataSource, historyStore, isFullscreen, isMobile = false, onToggleFullscreen, overlayContainer, statusColors} = props
    const readOnly = useProjectReadOnly()
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => dataSource.pasteImage('board-card', file, insertMarkdown),
        [dataSource],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = dataSource.getActiveCard('board-card')
        if (!card) throw new Error('Cannot attach files without an active board card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [dataSource])
    const ToolbarContents = useCallback(
        () => (
            <CardPopupToolbarControls
                cardTypes={cardTypes}
                dataSource={dataSource}
                isFullscreen={isFullscreen}
                isMobile={isMobile}
                onToggleFullscreen={onToggleFullscreen}
                readOnly={readOnly}
                statusColors={statusColors}
            />
        ),
        [cardTypes, dataSource, isFullscreen, isMobile, onToggleFullscreen, readOnly, statusColors],
    )
    return (
        <Box
            sx={{
                '& .mdxeditor-content': {
                    boxSizing: 'border-box',
                    minHeight: 220,
                    padding: '26px 28px 32px',
                },
                '& [class*="_toolbarButton_"], & [class*="_toolbarToggleItem_"]': {
                    alignItems: 'center',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    height: 30,
                    justifyContent: 'center',
                    width: 30,
                },
                '& [class*="_toolbarButton_"]:hover, & [class*="_toolbarToggleItem_"]:hover': {
                    backgroundColor: 'background.paper',
                    color: 'text.primary',
                },
                '& [class*="_toolbarRoot_"]': {
                    backgroundColor: 'action.selected',
                    borderRadius: '9px',
                    boxSizing: 'border-box',
                    color: 'text.secondary',
                    flexShrink: 0,
                    height: 40,
                    margin: '14px 20px 0',
                    padding: '0 6px',
                    width: 'auto',
                },
                '& [class*="_toolbarRoot_"] div[role="separator"]': {
                    borderColor: 'divider',
                    height: 20,
                    margin: '0 4px',
                },
                flex: 1,
                minHeight: 0,
                overflow: 'auto',
            }}
        >
            <MarkdownEditor
                attachmentHandler={handleAttachments}
                binding="board-card"
                dataSource={dataSource}
                historyStore={historyStore}
                imagePasteHandler={handleImagePaste}
                overlayContainer={overlayContainer}
                readOnly={readOnly}
                toolbarContents={ToolbarContents}
            />
        </Box>
    )
})

